function verify($ok,$label){global $checks;if(!$ok)throw new Exception('FAILED '.$label);$checks++;echo 'PASS '.$label."\n";}
function reject($fn,$label){try{$fn();}catch(Exception $e){verify(true,$label);return;}verify(false,$label);}
try{
$db=Yii::app()->db;$parent=new Category;$parent->name='Test parent';$parent->slug='cms-test-parent';$parent->description='';verify(Hierarchy::save($parent),'create root category');$child=new Category;$child->name='Test child';$child->slug='cms-test-child';$child->description='';$child->parent_id=$parent->id;verify(Hierarchy::save($child),'create child category');$parent->parent_id=$child->id;verify(!Hierarchy::save($parent),'category cycle rejected');$child->parent_id=999999;verify(!$child->validate(),'missing category parent rejected');verify(in_array((int)$child->id,Hierarchy::descendants(Hierarchy::rows('categories'),$parent->id),true),'descendant category filtering');verify(!isset(Category::options($parent->id)[$child->id]),'parent selector omits descendants');
$m=new MenuItem;$m->label='Unsafe';$m->location='header';$m->url='javascript:alert(1)';verify(!$m->validate(),'script menu URL rejected');$m->url='//evil.test';verify(!$m->validate(),'protocol relative URL rejected');$m->url='/shop';$m->is_active=1;verify(Hierarchy::save($m),'internal menu URL accepted');$n=new MenuItem;$n->label='Wrong location';$n->url='/blog';$n->location='footer';$n->parent_id=$m->id;verify(!$n->validate(),'menu parents must share location');$m->parent_id=$m->id;verify(!$m->validate(),'self menu parent rejected');
$p=Product::model()->find(array('order'=>'id'));$p->display_layout='unknown';verify(!$p->validate(),'unknown product layout rejected');$p->display_layout='gallery';$p->card_layout='compact';verify($p->save(),'per product presentation saves');
$c=new ProductCollection;$c->title='Test collection';$c->slug='cms-test-collection';$c->description='Test';$c->is_active=1;verify($c->save(),'collection saves');$ids=$db->createCommand("SELECT id FROM products WHERE status='published' ORDER BY id LIMIT 2")->queryColumn();foreach(array_reverse($ids) as $position=>$id)$db->createCommand()->insert('collection_products',array('collection_id'=>$c->id,'product_id'=>$id,'position'=>$position));verify(array_map('intval',$c->productIds())===array_reverse(array_map('intval',$ids)),'collection order retained');verify(count($c->products(1))===1,'collection query respects limit');
$options=ThemeOptions::defaults('market-light');$options['hero_media']='';$blocks=ThemeOptions::blocks('market-light');ThemeOptions::save('market-light',$options,$blocks);verify(ThemeOptions::get('market-light')['product_layout']==='split','theme customization persists');$blocks[0]['block_type']='../../private';reject(function()use($options,$blocks){ThemeOptions::save('market-light',$options,$blocks);},'arbitrary template blocks rejected');$options['hero_media']='999999';reject(function()use($options){ThemeOptions::save('market-light',$options,array());},'missing theme media rejected');
$stock=$p->stock;$orders=(int)$db->createCommand('SELECT COUNT(*) FROM orders')->queryScalar();ShopSettings::set('commerce_enabled','0');verify(!Commerce::enabled(),'catalog mode enabled');reject(function()use($p){OrderService::reserve(array($p->id=>1),array());},'catalog rejects direct reservation');verify((int)$db->createCommand('SELECT COUNT(*) FROM orders')->queryScalar()===$orders && Product::model()->findByPk($p->id)->stock==$stock,'catalog rejection creates no order or stock write');ShopSettings::set('catalog_show_prices','0');verify(!Commerce::showPrices(),'catalog prices can be hidden');ShopSettings::set('commerce_enabled','1');verify(Commerce::showPrices(),'commerce always shows prices');
